@dataclass(frozen=True)
class Monto:
    valor: Decimal
    moneda: Moneda

    def __add__(self, otro: 'Monto') -> 'Monto':
        if self.moneda != otro.moneda:
            raise MonedasDistintas(self.moneda, otro.moneda)
        return Monto(self.valor + otro.valor, self.moneda)

class Pedido:
    def confirmar(self) -> None:
        if not self._lineas:
            raise PedidoVacio(self.id)
        self._estado = EstadoPedido.CONFIRMADO

def retirar(self, monto):
    if monto > self.saldo:
        return None

class SaldoInsuficiente(ErrorDeDominio): ...

def retirar(self, monto: Monto) -> None:
    if monto > self.saldo:
        raise SaldoInsuficiente(self.saldo, monto)

class Canal(Protocol):
    def enviar(self, mensaje: Mensaje) -> None: ...

@dataclass
class Notificador:
    canales: list[Canal]
